<script lang="ts">
 import { onMount } from 'svelte';import { SvelteMap } from 'svelte/reactivity';import { resolve } from '$app/paths';import { offlineItems,offlineKey,unlockDetails,removeOffline,type OfflineItem,type OfflineDetails } from '../../lib/offline-vault';
 let items=$state<OfflineItem[]>([]);let details=$state<Record<string,OfflineDetails>>({});let phrase=$state('');let error=$state('');let selected=$state('');let busy=$state(false);const keys=new SvelteMap<string,CryptoKey>();
 let video:HTMLVideoElement|undefined;
 function stop(){if(video){video.pause();video.removeAttribute('src');video.load();}selected='';}
 function lock(){stop();details={};keys.clear();}
 async function load(){items=await offlineItems();}
 onMount(()=>{void load().catch(()=>error='Stockage local indisponible.');const respond=(event:MessageEvent)=>{if(event.data?.type==='offline-key'&&event.ports[0])event.ports[0].postMessage(keys.get(event.data.id));};navigator.serviceWorker?.addEventListener('message',respond);return()=>{navigator.serviceWorker?.removeEventListener('message',respond);lock();};});
 async function unlock(event:SubmitEvent){event.preventDefault();busy=true;error='';let opened=0;try{for(const item of items.filter(item=>item.complete)){try{const key=await offlineKey(phrase,item.salt);const value=await unlockDetails(item,key);keys.set(item.id,key);details[item.id]=value;opened++;}catch{/* A different phrase leaves the item locked. */}}if(!opened)error='Aucun téléchargement ne correspond à cette phrase.';}finally{phrase='';busy=false;}}
 async function remove(id:string){if(selected===id)stop();keys.delete(id);delete details[id];await removeOffline(id);await load();}
</script>
<main><a href={resolve('/')}>Retour à la médiathèque</a><h1>Téléchargements hors ligne</h1><p>Les fichiers restent chiffrés sur cet appareil. Saisissez votre phrase pour les déverrouiller pendant cette visite.</p><form onsubmit={unlock}><label>Phrase de déverrouillage<input type="password" autocomplete="current-password" required bind:value={phrase} /></label><button disabled={busy}>Déverrouiller</button><button type="button" onclick={lock}>Verrouiller</button></form>
{#each items as item(item.id)}<article><div><strong>{details[item.id]?.title??(item.complete?'Téléchargement verrouillé':'Téléchargement incomplet')}</strong><p>{Math.round(item.size/1024**2)} Mio</p></div><button disabled={!details[item.id]} onclick={()=>selected=item.id}>Lire</button><button onclick={()=>remove(item.id).catch(()=>error='Suppression impossible.')}>Supprimer</button></article>{:else}<p>Aucun téléchargement enregistré.</p>{/each}
{#if selected&&details[selected]}<video bind:this={video} controls autoplay playsinline src={`/app/offline-media/${selected}`} onerror={()=>error='Lecture impossible : déverrouillez le fichier ou vérifiez sa compatibilité avec ce navigateur.'}><track kind="captions" /></video>{/if}{#if error}<p role="alert">{error}</p>{/if}
</main>
<style>main { max-width:1000px;margin:auto;padding:24px; } form,label,article { display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:16px 0; } article { border-bottom:1px solid var(--color-line);padding:16px 0; } article>div { flex:1; } input,button { padding:10px;background:var(--color-surface);color:var(--color-text);border:1px solid var(--color-line);border-radius:8px; } a { color:var(--color-accent); } video { width:100%;max-height:70vh; } </style>
